{"point":{"id":"changes","title":"Repository Change Proposals","rationale":"ChangeSessionService captures repository-scoped canvases and Git hunks into isolated proposals, applies the shared controller operations, and retains baseline/proposed history for review. Acceptance checks captured versions before atomic catalog publication. DiffSession workflows and deduplicated push intake feed this same proposal lifecycle.","sourcePaths":["application/mapping/changes/changeSessionService.ts","application/mapping/changes/diffSessionWorkflowService.ts","application/mapping/changes/diffSessionTools.ts","application/core/integrations/pushIntegrationService.ts","domain/mapping/changes/diagramChangeSession.ts","domain/mapping/changes/diffTree.ts","domain/mapping/changes/diagramMigration.ts","infrastructure/mapping/changes/changeSessionRecords.ts","infrastructure/mapping/changes/diagramChangeSessionStore.ts","infrastructure/core/persistence/repositoryHunks.ts","infrastructure/core/integrations/gitPushSource.ts","src/features/mapping/changes/ChangeSessionPreview.tsx"],"relationships":[{"pointId":"canvas","label":"forks histories and applies shared controller operations","kind":"call"},{"pointId":"persistence","label":"publishes accepted canvases and recovery receipts","kind":"call"},{"pointId":"live-agent","label":"uses agent tools during proposal materialization","kind":"call"}]},"sources":[{"path":"application/mapping/changes/changeSessionService.ts","text":"import { importDiagramRevision } from '../../../domain/core/diagrams/diagramRevisionStore';
import { buildChangeTreemaps } from '../../../domain/mapping/changes/changeTreemap';
import { defaultDiffTree, diffTreeSummary, diffTreeNodes, resolveDiffTreeHunks, validateDiffTree, writeDiffTree, type DiffTreeInput } from '../../../domain/mapping/changes/diffTree';
import type { RepositoryContext } from '../../../domain/core/repositories/repository';
import type { GitDiffHunk } from '../../../domain/core/diffs/gitDiffHunk';
import { migrationIssues, type DiagramMigration } from '../../../domain/mapping/changes/diagramMigration';
import { canvasDisplayNodes } from '../../../domain/mapping/workspace/canvasDisplayNode';
import { DefaultCanvasHistoryService } from '../../../domain/core/diagrams/canvasHistoryService';
import { historyFromRevision, documentFromRevision } from '../../../domain/core/diagrams/projectDiagramCanvas';
import { diagramContentNodes } from '../../../domain/core/diagrams/diagramContentNodes';
import { createHash, randomUUID } from 'node:crypto';
import type { DiagramRepository } from '../../core/ports/diagramRepository';
import type { CanvasSessionPort } from '../agent/ports';
import type { LiveDocumentSnapshot, LiveDocumentState } from '../../../domain/mapping/agent/contracts';
import type { DiagramChangeSessionRepository } from './ports';
import { summarizeChangeSession, type ChangeDocumentState, type ChangeSessionDocument, type DiagramChangeSession, type DiagramChange } from '../../../domain/mapping/changes/diagramChangeSession';
