import type { ChangeSessionWriteScope, DiagramChangeSessionRepository } from '../../../application/mapping/changes/ports';
import { summarizeChangeSession, type ChangeSessionSummary, type ChangeSessionPreview, type DiagramChangeSession } from '../../../domain/mapping/changes/diagramChangeSession';
import { ChangeSessionRecords, type SessionWrite } from './changeSessionRecords';
import { changeSessionWorker } from './changeSessionWorker';

/** Metadata reads remain on the request thread; hydration/migration/writes can run in a worker. */
export class DiagramChangeSessionStore implements DiagramChangeSessionRepository {
  private readonly records: ChangeSessionRecords;
  private readonly tokens = new WeakMap<DiagramChangeSession, string>();
  constructor(private readonly root: string, diagrams?: DiagramPersistence, private readonly background = false) {
    this.records = new ChangeSessionRecords(root, diagrams);
  }
  listSummaries(projectId: string) { return this.records.listSummaries(projectId, id => this.readSummary(projectId, id)); }
  readSummary(projectId: string, id: string): Promise<ChangeSessionSummary> {
    return this.records.readSummary(projectId, id, this.background ? () => changeSessionWorker(this.root).request('readSummary', [projectId, id]) : undefined);
  }
  readPreview(projectId: string, id: string, documentId: string): Promise<ChangeSessionPreview> {
    return this.background ? changeSessionWorker(this.root).request('readPreview', [projectId, id, documentId]) : this.records.readPreview(projectId, id, documentId);
  }
  async readDiffTree(projectId: string, id: string) {
    return this.background ? changeSessionWorker(this.root).request<Awaited<ReturnType<ChangeSessionRecords['readDiffTree']>>>('readDiffTree', [projectId, id]) : this.records.readDiffTree(projectId, id);
  }
  async read(projectId: string, id: string) {
    const result = this.background ? await changeSessionWorker(this.root).request<{ session: DiagramChangeSession; token: string }>('read', [projectId, id]) : await this.records.read(projectId, id);
    // Worker messages carry portable histories; register their revisions in this
    // process before controllers fork or edit those diagrams.
    if (this.background) await restoreDiagramData(result.session.documents.map(document => document.history), {
      get: async () => { throw Error('Worker returned an unresolved diagram record'); },
      put: async () => { throw Error('Worker restoration is read-only'); }
    }, 'current');
    this.tokens.set(result.session, result.token); return result.session;
  }
  async write(session: DiagramChangeSession, scope?: ChangeSessionWriteScope) {
    const input: SessionWrite = { ...(!scope || scope.diffTree ? { diffTree: session.diffTree } : {}), summary: summarizeChangeSession(session), expected: this.tokens.get(session),
      documents: scope ? session.documents.filter(doc => scope.documents.includes(doc.id)) : session.documents,
      receipts: scope ? Object.fromEntries(scope.receipts.map(key => [key, session.receipts[key]])) : session.receipts };
    const token = this.background ? await changeSessionWorker(this.root).request<string>('write', [input]) : await this.records.write(input);
    this.tokens.set(session, token);
  }
}
"},{"path":"infrastructure/core/persistence/repositoryHunks.ts","text":"import { createHash } from 'node:crypto';
import { execFileAsync } from './shared';
import type { RepositoryContext } from '../../../domain/core/repositories/repository';
import { parseGitFileDiff, type GitDiffHunk } from '../../../domain/core/diffs/gitDiffHunk';

const MAX_BYTES = 8 * 1024 * 1024;
/** Immutable first-parent commit diffs, or an explicit push base-to-head comparison. */
export async function captureGitHunks(root: string, context: RepositoryContext): Promise<GitDiffHunk[]> {
  const git = async (...args: string[]) => (await execFileAsync('git', ['--literal-pathspecs', '-C', root, ...args], {
    encoding: 'utf8', maxBuffer: MAX_BYTES, timeout: 15000, env: { ...process.env, LC_ALL: 'C', GIT_NO_REPLACE_OBJECTS: '1' }
  })).stdout;
  const hunks: GitDiffHunk[] = [];
  let bytes = 0;
  for (const commit of context.comparisonBase !== undefined ? [context.head] : context.commits) {
    // Read the actual object: rev-list treats a shallow boundary as a root.
    const object = await git('cat-file', 'commit', commit);
    const headers = object.split('\n\n', 1)[0];
    const parent = context.comparisonBase !== undefined ? context.comparisonBase : headers.match(/^parent ([a-f0-9]+)$/m)?.[1] ?? null;
    const base = parent ?? createHash(commit.length === 64 ? 'sha256' : 'sha1').update('tree 0\0').digest('hex');
    const entries = (await git('diff', '--no-ext-diff', '--no-textconv', '--no-renames', '--name-status', '-z', base, commit, '--')).split('\0');
    entries.pop();
    for (let index = 0; index < entries.length; index += 2) {
      const status = entries[index], file = entries[index + 1];
      if (!file || !['A', 'M', 'D', 'T'].includes(status)) throw Error('Unsupported Git diff entry');
      const patch = await git('-c', 'core.quotePath=true', 'diff', '--no-ext-diff', '--no-textconv', '--no-renames', '--no-color',
        '--full-index', '--diff-algorithm=myers', '--no-indent-heuristic', '--unified=3', '--inter-hunk-context=0', '--src-prefix=a/', '--dst-prefix=b/', base, commit, '--', file);
      bytes += Buffer.byteLength(patch);
      if (bytes > MAX_BYTES) throw Error('Diff exceeds 8 MiB; select fewer commits');
      hunks.push(...parseGitFileDiff({ repositoryId: context.repositoryId, commit, parent, path: file, status: status as GitDiffHunk['status'] }, patch));
      if (hunks.length > 2000) throw Error('Diff exceeds 2000 hunks; select fewer commits');
    }
  }
  return hunks;
}
"},{"path":"infrastructure/core/integrations/gitPushSource.ts","text":"import { createHash } from 'node:crypto';
import type { RepositoryRegistry } from '../../../application/core/ports/repositoryRegistry';
import type { PushSource } from '../../../application/core/integrations/ports';
import type { PushEvent, RepositoryConnection } from '../../../domain/core/integrations/pushIntegration';
import { discoverRepository, execFileAsync } from '../persistence/shared';

export class GitPushSource implements PushSource {
  constructor(private readonly repositories: RepositoryRegistry,
    private readonly credentials: (name: string) => string | undefined = name => process.env[name]) {}
  private async root(connection: RepositoryConnection) {
    const repository = (await this.repositories.list()).find(repo => repo.id === connection.repositoryId);
    if (!repository) throw Error('Register the local repository before connecting its remote');
    for (const root of repository.checkoutRoots) {
      const discovered = await discoverRepository(root).catch(() => undefined);
      if (discovered?.repositoryIdentity === repository.identity) return root;
    }
    throw Error('Connected repository checkout is unavailable');
  }
  async validateConnection(connection: RepositoryConnection) { await this.root(connection); }
  async resolve(connection: RepositoryConnection, event: PushEvent) {
    if (!event.after) return { kind: 'delete' as const, commits: [], hasChanges: false };
    const root = await this.root(connection);
    const token = connection.credentialEnv ? this.credentials(connection.credentialEnv) : undefined;
    if (connection.credentialEnv && !token) throw Error(`Set ${connection.credentialEnv} on the server before fetching pushes`);
    const env: NodeJS.ProcessEnv = { ...process.env, GIT_TERMINAL_PROMPT: '0', GIT_NO_REPLACE_OBJECTS: '1',
      GIT_CONFIG_COUNT: token ? '2' : '1', GIT_CONFIG_KEY_0: 'http.followRedirects', GIT_CONFIG_VALUE_0: 'false',
      ...(token ? { GIT_CONFIG_KEY_1: `http.${connection.remoteUrl}.extraHeader`, GIT_CONFIG_VALUE_1: `Authorization: Bearer ${token}` } : {}) };
    const git = async (...args: string[]) => (await execFileAsync('git', ['-C', root, ...args],
      { encoding: 'utf8', maxBuffer: 8 * 1024 * 1024, timeout: 120000, env })).stdout.trim();
    const hasCommit = async (sha: string) => {
      try { await git('cat-file', '-e', `${sha}^{commit}`); return true; } catch { return false; }
    };
    for (const sha of [...new Set([event.after, ...(event.before ? [event.before] : [])])]) {
      if (!await hasCommit(sha)) {
        try { await git('fetch', '--no-tags', '--no-write-fetch-head', '--', connection.remoteUrl, sha); }
        catch { throw Error(`Unable to fetch pushed commit ${sha}`); }
      }
      if (!await hasCommit(sha)) throw Error(`Push references unavailable commit ${sha}`);
    }
    if (await git('rev-parse', '--is-shallow-repository') === 'true') {
      throw Error('Push commit discovery requires a full clone; unshallow the registered repository');
    }
    // Always walk the pinned graph. Artifacts' commits[] may be truncated, and
    // branch HEAD may already have moved again by the time this event arrives.
    const commits = (await git('rev-list', '--reverse', '--topo-order', event.after,
      ...(event.before ? [`^${event.before}`] : []), '--')).split('\n').filter(Boolean);
    if (commits.length > 2000) throw Error('Push exceeds the supported 2000-commit limit');
    let kind: 'update' | 'new-branch' | 'force-push' = event.before ? 'update' : 'new-branch';
    if (event.before) {
      try { await git('merge-base', '--is-ancestor', event.before, event.after); }
      catch (error) {
        if ((error as { code?: number }).code !== 1) throw error;
        kind = 'force-push';
      }
    }
    const emptyTree = createHash(event.after.length === 64 ? 'sha256' : 'sha1').update('tree 0\0').digest('hex');
    const afterTree = await git('rev-parse', `${event.after}^{tree}`);
    const beforeTree = event.before ? await git('rev-parse', `${event.before}^{tree}`) : emptyTree;
    return { kind, commits, hasChanges: beforeTree !== afterTree };
  }
}
"},{"path":"src/features/mapping/changes/ChangeSessionPreview.tsx","text":"import { DiagramDisplayToggle } from '../../../shared/diagrams/DiagramDisplayToggle';
import type { CanvasTransform } from '../../../../domain/core/diagrams/diagramCanvas';
import { useTreemapRegionSelection } from '../treemap/useTreemapRegionSelection';
import { treemapCanvasTiles, treemapCanvasRegions } from './treemapCanvasTiles';
import { diagramColorStyle, type TreemapDiagramColor } from './treemapDiagramColors';
import { changeMigrationPreview, migrationMarkKey, type MigrationPreview } from './changeMigrationPreview';
import { useDiffTreeData } from './diffTreeData';
import { diffTreeCoverage, diagramCoverage, coverageLabel, coverageTitle, type DiffCoverage } from './diffTreeCoverage';
import { diagramContentNodes } from '../../../../domain/core/diagrams/diagramContentNodes';
import { ChangePreviewState } from './changePreviewState';
import { useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ChangePreviewDocument, ChangeSessionPreview as Preview, DiagramChangeSession } from '../../../../domain/mapping/changes/diagramChangeSession';
import { diffChangeDocument } from '../../../../domain/mapping/changes/changeDocumentDiff';
import { DraggableDiagramCanvas } from '../../../shared/diagrams/DraggableDiagramCanvas';
import { DiagramText } from '../../../shared/diagrams/DiagramText';
import { PanelConnector } from '../../../shared/diagrams/PanelConnector';
import { DiagramSubtreeControls } from '../canvas/DiagramSubtreeControls';
import { useEndpointGeometry } from '../canvas/useEndpointGeometry';
import { acceptChangeSession, readChangeSession, type DisplayModeChange } from './changeSessionApi';
import { projectDiagramComparisons, layoutDiagramComparisons, type PreviewTextRun } from '../../../../domain/mapping/workspace/diagramDiffProjection';
import type { SearchDocument } from '../search/diagramSearchService';
import { SearchHighlight, type DiagramFocus } from '../search/SearchHighlight';
import type { DiagramLineSearchResult } from '../../../../domain/mapping/search/diagramSearch';
import { revealSearchMatches } from '../search/revealSearchMatches';
import '../canvas/diagramConnections.css';
import './changeSessions.css';

export function ChangeSessionPreview(props: { treemapColors?: readonly TreemapDiagramColor[]; compact?: boolean; mode: DisplayModeChange; onSelect: (mode: DisplayModeChange) => void;
  onSearchDocument?: (document: SearchDocument) => void; searchFocus?: DiagramFocus;
  searchMatches?: readonly DiagramLineSearchResult[];
  onOpenAccepted: (session: Omit<DiagramChangeSession, 'receipts'>, documentId: string) => Promise<void> }) {
  const [loaded, setLoaded] = useState<{ session: Preview; diff: ReturnType<typeof diffChangeDocument> }>();
  const session = loaded?.session;
  const [error, setError] = useState('');
  const [accepting, setAccepting] = useState(false);
  const pendingAcceptance = useRef<{ sessionId: string; version: number; requestId: string } | undefined>(undefined);
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>, version: number | undefined;
    setLoaded(undefined); setError('');
    const worker = new Worker(new URL('./changePreview.worker.ts', import.meta.url), { type: 'module' });
    const refresh = () => {
      const endpoint = new URL(`${import.meta.env.BASE_URL}api/mapping/agent/change-sessions/${encodeURIComponent(props.mode.sessionId)}/preview`, location.href);
      endpoint.searchParams.set('documentId', props.mode.documentId);
      if (version !== undefined) endpoint.searchParams.set('version', String(version));
      worker.postMessage({ endpoint: endpoint.href });
    };
    worker.onmessage = ({ data }: MessageEvent<{ session?: Preview | null; diff?: ReturnType<typeof diffChangeDocument>; error?: string }>) => {
      if (data.error) setError(data.error);
      else if (data.session && data.diff) { version = data.session.version; setLoaded({ session: data.session, diff: data.diff }); setError(''); }
      if (data.session?.status !== 'accepted' && data.session?.status !== 'archived') timer = setTimeout(refresh, 2000);
    };
    worker.onerror = () => setError('Preview worker stopped. Reopen the proposal to retry.');
    refresh(); return () => { clearTimeout(timer); worker.terminate(); };
  }, [props.mode.sessionId, props.mode.documentId]);
  const doc = session?.document;
  const { data: treeData } = useDiffTreeData(session?.diffTree ? props.mode.sessionId : undefined);
  const coverage = useMemo(() => treeData ? diffTreeCoverage(treeData) : undefined, [treeData]);
  const migrations = useMemo(() => doc ? changeMigrationPreview(doc, session?.migrations ?? []) : undefined, [doc, session?.migrations]);
  const selectedEndpoint = migrations?.endpoints.find(e => e.migration.id === props.mode.migrationId && e.role === props.mode.migrationRole);
  useEffect(() => {
    if (doc && session?.id === props.mode.sessionId) props.onSearchDocument?.({
      id: `proposal:${session.id}:${doc.id}`, name: `${doc.name} (proposal)`, scope: 'proposal', document: doc.proposed.document
    });
  }, [doc, session?.id, props.mode.sessionId, props.onSearchDocument]);
  const change = session?.changes.find(c => c.id === props.mode.changeId);
  const diff = loaded?.diff;
  const modifiedDiagramIds = useMemo(() => new Set(session?.changes.flatMap(change =>
    change.documentId === doc?.id && change.type === 1 && change.nodeId ? [change.nodeId] : [])), [session, doc?.id]);
  const accept = async () => {
    if (!session || accepting) return;
    if (pendingAcceptance.current?.sessionId !== session.id || pendingAcceptance.current.version !== session.version)
      pendingAcceptance.current = { sessionId: session.id, version: session.version, requestId: crypto.randomUUID() };
    const request = pendingAcceptance.current;
    setAccepting(true); setError('');
    try {
      await acceptChangeSession(request.sessionId, request.version, request.requestId);
      const accepted = await readChangeSession(request.sessionId);
      await props.onOpenAccepted(accepted, props.mode.documentId);
    } catch (e) { setError(e instanceof Error ? e.message : String(e)); }
    finally { setAccepting(false); }
  };
  return <div className="change-session-preview" data-change-session={props.mode.sessionId}>
    {session && <div className="change-session-actions">
      <span>{session.status === 'accepted' ? 'Accepted — original review diff retained' : session.title}</span>
      {session.head && <small title={`Selected commits: ${(session.commits ?? []).join(', ') || 'none'}`}>HEAD {session.head.slice(0, 12)} · {session.commits?.length ?? 0} commits</small>}
      {session.diffTree && !props.compact && <button onClick={() => props.onSelect({ ...props.mode, view: 'diff-tree' })}>Diff tree</button>}
      {session.status === 'ready' && <button disabled={accepting} onClick={() => void accept()}>{accepting ? 'Accepting…' : 'Accept all changes'}</button>}
      {session.status === 'draft' && <span>Mark this proposal ready before accepting.</span>}
      {session.status === 'accepted' && <button onClick={() => void readChangeSession(session.id).then(full => props.onOpenAccepted(full, props.mode.documentId))
        .catch(e => setError(e instanceof Error ? e.message : String(e)))}>Open canvas</button>}
    </div>}
    {error && <p className="change-preview-message" role="alert">{error}</p>}
    {doc
      ? <DiagramDiffCanvas key={`${session!.id}:${doc.id}:${doc.version}:${props.mode.migrationId ? props.mode.serial : ''}`} doc={doc}
          compact={props.compact} coverage={coverage} treemapColors={props.treemapColors} searchFocus={props.searchFocus}
          searchMatches={props.searchMatches}
          diff={diff!} modifiedDiagramIds={modifiedDiagramIds} migrations={migrations!} focusContentNodeId={props.mode.contentNodeId ?? selectedEndpoint?.focusContentNodeId}
          focusId={props.mode.displayNodeId ?? (selectedEndpoint?.focusContentNodeId ? selectedEndpoint.endpoint.displayNodeId : change?.nodeId)} serial={props.mode.serial} onJump={target => {
            const destination = session!.documents.find(d => d.representationId === target.representationId || d.id === target.representationId);
            if (!destination) { setError('Linked canvas is outside this change session'); return; }
            props.onSelect({ ...props.mode, documentId: destination.id, displayNodeId: target.displayNodeId, contentNodeId: target.contentNodeId, migrationId: undefined, migrationRole: undefined, changeId: session!.changes.find(c => c.documentId === destination.id && c.nodeId === target.displayNodeId)?.id, serial: props.mode.serial + 1 });
          }} />
      : <p className="change-preview-message">{session ? 'Select a canvas in Changes.' : 'Loading preview…'}</p>}
  </div>;
}
// Measure only when jumping: resizing an overlay must not move a panned canvas.
function previewFocusBounds(viewport: HTMLElement) {
  const bounds = viewport.getBoundingClientRect();
  let left = bounds.left, right = bounds.right, top = bounds.top;
  const workspace = viewport.closest('.mapping-viewport');
  for (const element of workspace?.querySelectorAll<HTMLElement>('.mapping-floating-pane, .window-panel, .diagram-search-panel') ?? []) {
    if (element.contains(viewport)) continue;
    const rect = element.getBoundingClientRect();
    if (!rect.width || !rect.height || rect.bottom <= bounds.top || rect.top >= bounds.bottom) continue;
    if (element.matches('.mapping-floating-pane')) left = Math.max(left, Math.min(bounds.right, rect.right + 12));
    else right = Math.min(right, Math.max(bounds.left, rect.left - 12));
  }
  const header = viewport.closest('.change-session-preview')?.querySelector('.change-session-actions')?.getBoundingClientRect();
  if (header?.height) top = Math.max(top, Math.min(bounds.bottom, header.bottom + 12));
  return { left, top, width: Math.max(0, right - left), height: Math.max(0, bounds.bottom - top) };
}

export function DiagramDiffCanvas({ onPromoteDiagram, display = 'diff', initialTransform, onTransformChange, removedDiagramIds, highlightAdded = false, treemapColors, coverage, compact, doc, focusId, focusContentNodeId, serial, onJump, diff, modifiedDiagramIds, migrations, searchFocus, searchMatches }: { onPromoteDiagram?: (id: string) => void; display?: 'regular' | 'diff'; initialTransform?: CanvasTransform; onTransformChange?: (value: CanvasTransform) => void; removedDiagramIds?: ReadonlySet<string>; highlightAdded?: boolean; treemapColors?: readonly TreemapDiagramColor[]; coverage?: DiffCoverage; compact?: boolean; doc: ChangePreviewDocument; focusId?: string; focusContentNodeId?: string; migrations: MigrationPreview; serial: number; searchFocus?: DiagramFocus;
  searchMatches?: readonly DiagramLineSearchResult[];
  diff: ReturnType<typeof diffChangeDocument>; modifiedDiagramIds: ReadonlySet<string>;
  onJump: NonNullable<Parameters<typeof DiagramText>[0]['onJump']> }) {
  const controller = useMemo(() => {
    const state = structuredClone(doc.proposed);
    // Lay out fully expanded diff bounds before freezing. Subsequent local folds
    // retain these positions, and routing reads this same prepared scene.
    if (display === 'diff') state.document.scene = layoutDiagramComparisons(state.document.scene, diff.diagrams, modifiedDiagramIds);
    state.canvas.diagramViews = {};
    return new ChangePreviewState(state, doc.version);
  }, [doc.id, doc.version, diff, modifiedDiagramIds, display]);
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot);
  useEffect(() => {
    if (!searchMatches?.length) return;
    controller.updateCanvas(current => {
      const revealed = revealSearchMatches(controller.getSnapshot().document.scene, current.diagramViews, searchMatches);
      return revealed.views === current.diagramViews ? current : { ...current, diagramViews: revealed.views };
    });
  }, [controller, searchMatches]);
  useEffect(() => {
    const result = searchFocus?.search;
    if (!result) return;
    controller.updateCanvas(current => {
      const view = current.diagramViews?.[result.displayNodeId];
      const content = controller.nodes().find(node => node.id === result.displayNodeId);
      if (!view || content?.layout !== 'grid' || content.content?.structure.kind !== 'tree'
