434:       const connected = doc.proposed.document.edges.some(edge => edge.target.displayNodeId === change.nodeId
435:         // The owner may be introduced/replaced by this proposal. Require its
436:         // containing diagram to exist in the baseline, not the owner node itself.
437:         && !!doc.baseline && !!connectionBox(doc.baseline.document.scene, edge.source.displayNodeId));
438:       if (!connected) throw new Error(`Added diagram needs an edge from an existing diagram: ${change.title}`);
